// A large generated diff and a deeply connected graph. A 2,000-function generated client is
// regenerated (skipped as generated), a JSON catalogue grows past the 1 MiB content cap, a chain
// of 30 changed steps each calls the next, and 120 changed jobs call one changed `log`, past the
// fan-out cap of 100.
import { type Files, type Fixture, lines, TSCONFIG } from './fixture.ts';

const STEPS = 30;
const range = (n: number) => Array.from({ length: n }, (_, i) => i);
const JOBS = 120;

const generated = (prefix: string) =>
  lines(
    '// @generated by api-codegen. DO NOT EDIT.',
    ...range(2000)
      .map((i) => [
        `export function ${prefix}Endpoint${i}(): string {`,
        `  return '/api/v2/endpoint/${i}';`,
        '}',
      ])
      .flat(),
  );

/** About 1.1 MiB of JSON, over the 1 MiB per-side content cap. */
const catalogue = (currency: string) =>
  `${JSON.stringify(
    range(16_000).map((i) => ({
      sku: `SKU-${String(i).padStart(6, '0')}`,
      price: (i % 500) + 0.99,
      currency,
    })),
    null,
    1,
  )}\n`;

const pipeline = (version: number) =>
  lines(
    ...range(STEPS)
      .map((i) => [
        `export function step${i}(input: number): number {`,
        i + 1 < STEPS
          ? `  return step${i + 1}(input + ${version});`
          : `  return input * ${version};`,
        '}',
        '',
      ])
      .flat(),
  );

const jobs = (level: string) =>
  lines(
    "import { log } from './log.ts';",
    '',
    ...range(JOBS)
      .map((i) => [`export function job${i}(): void {`, `  log('job ${i} done'${level});`, '}', ''])
      .flat(),
  );

const base: Files = {
  'tsconfig.json': TSCONFIG,
  'src/generated/client.ts': generated('get'),
  'data/catalogue.json': catalogue('USD'),
  'src/pipeline.ts': pipeline(1),
  'src/log.ts': lines(
    'export function log(message: string): void {',
    '  console.log(message);',
    '}',
  ),
  'src/jobs.ts': jobs(''),
};

const head: Files = {
  'src/generated/client.ts': generated('fetch'),
  'data/catalogue.json': catalogue('EUR'),
  'src/pipeline.ts': pipeline(2),
  'src/log.ts': lines(
    "export function log(message: string, level = 'info'): void {",
    '  console.log(`[${level}] ${message}`);',
    '}',
  ),
  'src/jobs.ts': jobs(", 'debug'"),
};

export const largeGenerated: Fixture = {
  name: 'large-generated',
  summary:
    'A large generated diff, an oversized data file, a deep call chain and a capped fan-out.',
  base,
  head,
  expected: {
    files: [
      'src/generated/client.ts git-only generated',
      'data/catalogue.json git-only too-large',
      'src/pipeline.ts structural',
      'src/log.ts structural',
      'src/jobs.ts structural',
    ],
    nodes: [
      'file src/generated/client.ts',
      'file data/catalogue.json',
      ...range(STEPS).map((i) => `symbol step${i}`),
      'symbol log',
      ...range(JOBS).map((i) => `symbol job${i}`),
    ],
    // Every job is a node, but only the first 100 callers keep their edge.
    edges: [
      ...range(STEPS - 1).map((i) => `step${i} calls step${i + 1} (both)`),
      ...range(100).map((i) => `job${i} calls log (both)`),
    ],
    caps: ['log calls 100/120'],
  },
  // log gains a level, and every job passes one: the contract before its callers, including the
  // 20 over the fan-out cap. The pipeline's version bump is a separate change.
  plan: {
    order: [[['log'], range(JOBS).map((i) => `job${i}`)]],
    apart: [range(STEPS).map((i) => `step${i}`), ['log', ...range(JOBS).map((i) => `job${i}`)]],
  },
  later: [
    'M1: generation stays within the #40 time and size thresholds.',
    'M3: the graph collapses the 151 symbols into groups, and the cap reads "Showing 100 of 120".',
  ],
};
